/* Adjustable file panes and task tray; no task or account state is modified. */
(() => {
  'use strict';
  const frame = document.querySelector('.window');
  const workspace = document.querySelector('.workspace');
  const queue = document.querySelector('.queue');
  if (!frame || !workspace || !queue) return;
  const storageKey = 'wemove.layout.v2';
  let state = { left: 0.5, queue: 0.22 };
  try {
    const saved = JSON.parse(localStorage.getItem(storageKey));
    if (!saved) {
      const legacy = JSON.parse(localStorage.getItem('wemove.layout.v1'));
      if (Number.isFinite(legacy?.left)) state.left = legacy.left;
    }
    for (const key of ['left', 'queue']) if (Number.isFinite(saved?.[key])) state[key] = saved[key];
  } catch {}
  const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
  const makeHandle = (parent, axis, label) => {
    const handle = document.createElement('div');
    handle.className = `layout-handle ${axis}`;
    handle.tabIndex = 0;
    handle.setAttribute('role', 'separator');
    handle.setAttribute('aria-orientation', axis === 'vertical' ? 'vertical' : 'horizontal');
    handle.setAttribute('aria-label', label);
    handle.title = label + ' · 双击恢复 / Double-click to reset';
    parent.appendChild(handle);
    return handle;
  };
  const vertical = makeHandle(workspace, 'vertical', '调整左右栏宽度 / Resize file panes');
  const horizontal = makeHandle(queue, 'horizontal', '调整队列高度 / Resize transfer queue');
  function apply() {
    const width = workspace.clientWidth - 10;
    const minimum = Math.min(280, width * 0.4);
    state.left = clamp(state.left, minimum / Math.max(1, width), 1 - minimum / Math.max(1, width));
    workspace.style.gridTemplateColumns = `minmax(0, ${state.left}fr) 10px minmax(0, ${1 - state.left}fr)`;
    const header = frame.querySelector('.app-header').getBoundingClientRect().height;
    const footer = frame.querySelector('.statusbar').getBoundingClientRect().height;
    const available = frame.clientHeight - header - footer;
    const height = clamp(available * state.queue, 140, Math.max(140, available - 240));
    frame.style.gridTemplateRows = `${header}px minmax(0, 1fr) ${height}px ${footer}px`;
    vertical.setAttribute('aria-valuemin', '0');
    vertical.setAttribute('aria-valuemax', '100');
    vertical.setAttribute('aria-valuenow', String(Math.round(state.left * 100)));
    horizontal.setAttribute('aria-valuemin', '140');
    horizontal.setAttribute('aria-valuemax', String(Math.round(Math.max(140, available - 240))));
    horizontal.setAttribute('aria-valuenow', String(Math.round(height)));
  }
  function persist() { try { localStorage.setItem(storageKey, JSON.stringify(state)); } catch {} }
  function wire(handle, key) {
    let activePointer = null;
    handle.addEventListener('pointerdown', event => {
      if (event.button !== 0) return;
      activePointer = event.pointerId;
      handle.setPointerCapture(activePointer);
      handle.blur();
      event.preventDefault();
      document.body.classList.add('layout-dragging');
    });
    handle.addEventListener('pointermove', event => {
      if (activePointer !== event.pointerId) return;
      if (key === 'left') {
        const rect = workspace.getBoundingClientRect();
        state.left = (event.clientX - rect.left - 5) / (rect.width - 10);
      } else {
        const rect = frame.getBoundingClientRect();
        const footer = frame.querySelector('.statusbar').getBoundingClientRect().height;
        const header = frame.querySelector('.app-header').getBoundingClientRect().height;
        state.queue = (rect.bottom - footer - event.clientY) / (frame.clientHeight - header - footer);
      }
      apply();
    });
    const finish = () => { activePointer = null; document.body.classList.remove('layout-dragging'); persist(); };
    handle.addEventListener('pointerup', finish);
    handle.addEventListener('pointercancel', finish);
    handle.addEventListener('lostpointercapture', finish);
    handle.addEventListener('dblclick', () => { state[key] = key === 'left' ? 0.5 : 0.22; apply(); persist(); });
    handle.addEventListener('keydown', event => {
      const keys = key === 'left' ? ['ArrowLeft', 'ArrowRight'] : ['ArrowDown', 'ArrowUp'];
      if (!keys.includes(event.key)) return;
      event.preventDefault();
      state[key] += (event.key === keys[0] ? -1 : 1) * (event.shiftKey ? 0.1 : 0.02);
      apply(); persist();
    });
  }
  wire(vertical, 'left'); wire(horizontal, 'queue');
  new ResizeObserver(apply).observe(frame);
  apply();
})();

function buildExtendedForm(body,provider){
 const oauth=['gdrive','dropbox','box','pcloud'].includes(provider),form=el('form','extended-storage-form');
 if(oauth){body.append(el('p','',t('在浏览器中授权连接，凭据仅保存在本机。')));body.append(button(t('打开授权页面'),()=>action(async()=>{await api('/login',{provider,account:authAccount});$('auth-progress').hidden=false;poll()}),'primary'));const details=el('details');details.append(el('summary','',t('高级：使用已有 OAuth Token')));field(form,'token','OAuth Token JSON','password');details.append(form);body.append(details)}
 else{body.append(el('p','',t(provider==='nextcloud'?'填写 Nextcloud 的 WebDAV 地址和应用密码。':provider==='sftp'?'通过 SSH 连接；使用 known_hosts 校验服务器身份。':provider==='mega'?'使用 MEGA 邮箱和密码连接。暂不支持开启双重认证的账号。':'填写存储服务的连接信息。')));if(['nextcloud','webdav'].includes(provider))field(form,'endpoint',t('WebDAV 地址'),'url');if(['ftp','sftp','smb'].includes(provider)){field(form,'host',t('主机地址'));field(form,'port',t('端口'),'number',false);form.elements.port.value={ftp:21,sftp:22,smb:445}[provider]}
 field(form,'user',provider==='mega'?t('账号邮箱'):t('用户名'),provider==='mega'?'email':'text');field(form,'password',provider==='nextcloud'?t('应用密码'):t('密码'),'password');if(provider==='sftp')field(form,'knownHosts','SSH known_hosts');if(provider==='smb')field(form,'domain',t('域（可选）'),'text',false);if(provider==='ftp'){const label=el('label','',t('连接安全')),select=el('select');select.name='security';for(const [v,text]of [['explicit','FTPS · Explicit TLS'],['implicit','FTPS · Implicit TLS'],['none','FTP']]){const o=el('option','',text);o.value=v;select.append(o)}label.append(select);form.append(label)}body.append(form)}
 const submit=button(t('验证并连接'),null,'primary');submit.type='submit';const err=el('p','form-error');form.append(submit,err);form.onsubmit=async ev=>{ev.preventDefault();submit.disabled=true;err.textContent=t('正在验证…');try{const input={provider,account:authAccount};for(const e of form.elements)if(e.name)input[e.name]=e.value;await api('/credentials',input);for(const e of form.querySelectorAll('input[type=password]'))e.value='';$('connect-dialog').close();refreshProvider(provider)}catch(e){err.textContent=e.message}finally{submit.disabled=false}};
}
